/** RESULTS.md is a derived view of results.json; it is regenerated, never edited. */
import type { BenchResults } from "./bench";

type Json = Record<string, any>;

const row = (cells: Array<string | number>) => `| ${cells.join(" | ")} |`;
const pct = (part: number, whole: number) => (whole === 0 ? "n/a" : `${Math.round((100 * part) / whole)}%`);

export function renderMarkdown(results: BenchResults): string {
  const out: string[] = [
    "# Interface-blocks bench (Phase 0)",
    "",
    "Generated by `pnpm --filter @dspack-studio/block-bench bench` from `results.json`. Do not edit by hand.",
    "",
    `Token counts: ${results.tokenizer}. Bytes are exact UTF-8. Nothing here is provider-reported usage.`,
    "",
  ];
  for (const ref of results.references as Json[]) {
    out.push(`## ${ref.contract.name} ${ref.contract.version}`, "");
    out.push("### What the hosted model receives today (fresh generation, per governed context)", "");
    out.push(row(["Intent", "System tokens", "Schema-text tokens", "Messages tokens", "Total input tokens", "Schema share", "Request bytes"]));
    out.push(row(["---", "---:", "---:", "---:", "---:", "---:", "---:"]));
    for (const g of (ref.requests.generation as Json[]).filter((x) => x.mode === "fresh")) {
      const m = g.modelInput;
      out.push(row([g.intent, m.system.tokens, m.schemaText.tokens, m.messages.tokens, m.totalTokens, pct(m.schemaText.tokens, m.totalTokens), g.bodyBytes]));
    }
    out.push("", "### Planning requests", "");
    out.push(row(["Kind", "Goal", "Total input tokens", "Request bytes"]));
    out.push(row(["---", "---", "---:", "---:"]));
    for (const p of ref.requests.planning as Json[]) out.push(row([p.kind, p.goal, p.modelInput.totalTokens, p.bodyBytes]));
    out.push("", "### One surface, three representations (worked examples)", "");
    out.push(row(["Example", "dspack surface tokens", "A2UI messages tokens", "json-render spec tokens"]));
    out.push(row(["---", "---:", "---:", "---:"]));
    for (const o of ref.outputs as Json[]) {
      out.push(row([o.example, o.surface.tokens, o.a2ui.refusal ? "refused" : o.a2ui.tokens, o.jsonRender.refusal ? "refused" : o.jsonRender.tokens]));
    }
    out.push("", "### Draft blocks (provisional: drafts, not owner-approved)", "");
    out.push(row(["Block", "Intent", "Named call tokens", "Positional call tokens", "Expanded surface tokens", "Block schema tokens (named)", "Surface schema tokens today", "S1/S2/S3", "Emitted actions"]));
    out.push(row(["---", "---", "---:", "---:", "---:", "---:", "---:", "---", "---"]));
    for (const d of ref.drafts as Json[]) {
      out.push(
        row([
          d.block,
          d.intent,
          d.namedCall.tokens,
          d.positionalCall.tokens,
          d.expandedSurface.tokens,
          d.selectedBlockSchema.named.tokens,
          d.todaySurfaceSchemaTokens ?? "n/a",
          `${d.lint.S1}/${d.lint.S2}/${d.lint.S3}`,
          d.a2ui.refusal ? "refused" : (d.a2ui.actions as string[]).join(", ") || "none",
        ]),
      );
    }
    out.push("", `B0 parity: ${ref.parity.components} generation-schema components; component set ${ref.parity.componentsMatch ? "matches" : "DIFFERS"}; id-required set ${ref.parity.idRequiredMatch ? "matches" : "DIFFERS"} (${(ref.parity.idRequired as string[]).join(", ") || "none"}).`, "");
    if (ref.leak) {
      const l = ref.leak as Json;
      out.push(`### Structural validity is not governance (${l.scope})`, "");
      out.push(
        `${l.summary.s3FailingButStructurallyValid} of ${l.summary.s3FailingRecomputed} recorded live attempts that fail S3 against the current contract pass every structural check (A1-A3 on both A2UI versions, and the json-render J2/J3 offline check), out of ${l.liveAttempts} live attempts recorded. Recorded and recomputed verdicts disagree on ${l.summary.verdictDisagreements} row(s).`,
        "",
      );
      out.push(
        `Verdicts are recomputed against the current contract; each run was recorded against the contract digest shown, so a disagreement column is kept rather than assumed away.`,
        "",
      );
      out.push(row(["Fixture", "Attempt", "Adapter", "Recorded contract", "Recorded S1/S2/S3", "Recomputed S1/S2/S3", "A2UI", "json-render"]));
      out.push(row(["---", "---:", "---", "---", "---", "---", "---", "---"]));
      for (const r of l.rows as Json[]) {
        const a2ui = r.a2ui.refusal ? "refused" : Object.values(r.a2ui.gates as Json).every((v: Json) => Object.values(v).every(Boolean)) ? "A1-A3 pass" : "gate fail";
        const jr = r.jsonRender.refusal ? "refused" : r.jsonRender.J2J3 ? "J2/J3 pass" : "check fail";
        const sha = r.recordedContractSha256 ? `${String(r.recordedContractSha256).slice(0, 12)}` : "n/a";
        out.push(row([r.fixture, r.attempt, r.adapterId, sha, `${r.recorded.S1}/${r.recorded.S2}/${r.recorded.S3}`, `${r.recomputed.S1}/${r.recomputed.S2}/${r.recomputed.S3}`, a2ui, jr]));
      }
      out.push("");
    }
  }
  return `${out.join("\n")}\n`;
}
